  ('mmd', 'Loss hours (D codes)', 'Machine-wise loss hours booked against the loss codes of the Operations Master', false, 500, 0, 6000, 30),
  ('mmd', 'WIP map & throughput alerts', 'Where every part lies, with quantity; alert when material stops moving against the throughput time', false, 700, 0, 10000, 40),
  ('mmd', 'Dashboards & Pareto', 'Production efficiency, OEE, capacity utilisation, rejection and rework rate; Pareto by part, defect, process, machine and operator', false, 900, 0, 15000, 50),
  ('mmd', 'Traceability & IATF records', 'Heat code to customer trace in both directions, entry voiding with reason, record export', false, 500, 0, 8000, 60)
