delete from console.app_features f where f.product_code = 'mmd' and f.name = 'Core platform'
   and not exists (select 1 from console.invoice_lines il where il.feature_id = f.id);
update console.app_features set price_year = price_month * 10 where product_code = 'mmd' and price_year = 0;
select console.sync_app_price('mmd');

-- ---------- tables ----------
create table if not exists console.mmd_counters (
  customer_id uuid not null references console.customers(id) on delete cascade, key text not null, n bigint not null default 0, sample boolean not null default false, primary key (customer_id, key));
create table if not exists console.mmd_route_sheets (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  rs_no text not null, part_code text not null, part_name text, customer_name text, qty numeric not null check (qty > 0),
  ops jsonb not null default '[]',                                  -- the process sequence at the time of issue: [{seq, op_no, name, machine, type: in|supplier, supplier, ct_sec}]
  rm_material text, rm_spec text, rm_size text, heat_code text, rm_kg numeric, mill_cert text, due_date date,
  status text not null default 'open' check (status in ('open', 'closed', 'cancelled')), notes text,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), closed_at timestamptz,
  unique (customer_id, rs_no));
create table if not exists console.mmd_tags (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  tag_no text not null, rs_id uuid not null references console.mmd_route_sheets(id) on delete cascade,
  kind text not null check (kind in ('RM', 'OK', 'REJ', 'REW')),
  seq int,                                       -- the operation this tag waits for (REW: the operation the rework belongs to); null at finished goods / rejection
  loc text not null check (loc in ('op', 'supplier', 'fg', 'rejection', 'rework', 'dispatched', 'closed')),
  qty numeric not null check (qty > 0), bal numeric not null check (bal >= 0),
  status text not null default 'open' check (status in ('open', 'used', 'void')),
  parent_tag uuid references console.mmd_tags(id), op_done int, entry_id uuid,
  reason_code text, reason text, spec text, actual text,
  dispo text, dispo_by text, dispo_at timestamptz, dispo_note text,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(),
  unique (customer_id, tag_no));
create table if not exists console.mmd_entries (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  rs_id uuid not null references console.mmd_route_sheets(id) on delete cascade, tag_id uuid references console.mmd_tags(id), dc_id uuid,
  kind text not null check (kind in ('process', 'rework', 'dc', 'grn', 'dispatch')),
  seq int, op_name text, machine text, ok_qty numeric not null default 0, rej_qty numeric not null default 0, rew_qty numeric not null default 0,
  entry_at timestamptz not null default now(), shift text, operator text, engineer text, note text,
  status text not null default 'ok' check (status in ('ok', 'void')), void_reason text, void_by text, void_at timestamptz,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now());
create table if not exists console.mmd_defects (       -- one row per rejection / rework reason line: the source of the Pareto charts and of the rejection and rework tags
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  entry_id uuid not null references console.mmd_entries(id) on delete cascade, rs_id uuid not null, tag_id uuid,
  kind text not null check (kind in ('rej', 'rew')), reason_code text, reason text, qty numeric not null check (qty > 0), spec text, actual text,
  part_code text, op_name text, machine text, operator text, entry_at timestamptz not null, void boolean not null default false, sample boolean not null default false);
create table if not exists console.mmd_dcs (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  dc_no text not null, rs_id uuid not null references console.mmd_route_sheets(id) on delete cascade, tag_id uuid references console.mmd_tags(id), seq int not null, op_name text,
  supplier_code text, supplier_name text, qty numeric not null check (qty > 0), received_qty numeric not null default 0, vehicle text, dispatch_at timestamptz not null default now(), expected_date date,
  status text not null default 'open' check (status in ('open', 'part', 'closed', 'cancelled')), note text,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(),
  unique (customer_id, dc_no));
create table if not exists console.mmd_grns (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  grn_no text not null, dc_id uuid not null references console.mmd_dcs(id) on delete cascade, rs_id uuid not null, entry_id uuid,
  ok_qty numeric not null default 0, rej_qty numeric not null default 0, inv_no text, received_at timestamptz not null default now(), note text,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(),
  unique (customer_id, grn_no));
create table if not exists console.mmd_loss (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  loss_date date not null, shift text, machine_code text not null, d_code text not null, d_name text, minutes numeric not null check (minutes > 0 and minutes <= 1440),
  rs_id uuid, part_code text, op_name text, remark text, operator text,
  status text not null default 'ok' check (status in ('ok', 'void')), void_reason text,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now());
create index if not exists mmd_tags_open on console.mmd_tags (customer_id, status, loc);
create index if not exists mmd_tags_rs on console.mmd_tags (rs_id);
create index if not exists mmd_entries_rs on console.mmd_entries (rs_id, seq);
create index if not exists mmd_entries_at on console.mmd_entries (customer_id, entry_at);
create index if not exists mmd_defects_at on console.mmd_defects (customer_id, entry_at);
create index if not exists mmd_loss_date on console.mmd_loss (customer_id, loss_date);
do $$ declare t text; begin foreach t in array array['mmd_counters','mmd_route_sheets','mmd_tags','mmd_entries','mmd_defects','mmd_dcs','mmd_grns','mmd_loss'] loop
  execute format('alter table console.%I enable row level security', t);
  execute format('drop policy if exists %I on console.%I', t || '_staff', t);
  execute format('create policy %I on console.%I for all to authenticated using (console.is_staff()) with check (console.is_staff())', t || '_staff', t);
end loop; end $$;

